// schema.ts
import { Schema, Document } from 'mongoose';

interface UserAttributes {
  name: string;
  email: string;
}

interface PostAttributes {
  title: string;
  content: string;
}

export interface UserDocument extends UserAttributes, Document {}
export interface PostDocument extends PostAttributes, Document {}

const userSchema = new Schema({
  name: { type: String, required: true },
  email: { type: String, required: true, unique: true },
});

const postSchema = new Schema({
  title: { type: String, required: true },
  content: { type: String, required: true },
});

export const UserModel = model('User', userSchema);
export const PostModel = model('Post', postSchema);
```

3. Create a `model.service.ts` file to handle the creation of MongoDB documents:

```typescript
// model.service.ts
import { Injectable } from '@nestjs/common';
import { Model } from 'mongoose';
import { UserModel, PostModel } from './schema';

@Injectable()
export class ModelService {
  constructor(private readonly userModel: Model<UserDocument>, private readonly postModel: Model<PostDocument>) {}

  async createUser(user: UserAttributes): Promise<UserDocument> {
    const createdUser = await this.userModel.create(user);
    return createdUser;
  }

  async createPost(post: PostAttributes): Promise<PostDocument> {
    const createdPost = await this.postModel.create(post);
    return createdPost;
  }
}
```

