using namespace std;

// Function to generate the Fibonacci sequence using recursion
vector<int> fibonacci(int n, int a, int b) {
    if (n == 0) {
        return vector<int>();
    }
    vector<int> result = fibonacci(n - 1, b, a + b);
    result.push_back(a);
    return result;
}

int main() {
    string input;
    int num1, num2, numSequenceElements;

    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);

    if (!(iss >> num1 >> num2)) {
        throw runtime_error("Invalid input. Please enter two integers.");
    }

    if (num1 < 0 || num2 < 0) {
        throw runtime_error("Both integers must be non-negative.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numSequenceElements;

    if (numSequenceElements <= 0) {
        throw runtime_error("The number of sequence elements must be positive.");
    }

    vector<int> sequence = fibonacci(numSequenceElements, num1, num2);

    cout << "Fibonacci Sequence:";
    for (auto it = sequence.begin(); it != sequence.end(); ++it) {
        cout << ' ' << *it;
    }
    cout << endl;

    return 0;
}
