        break;
    case 'sunset':
        $css_code = 'background-color: red;';
        break;
    case 'night':
        $css_code = 'background-color: black;';
        break;
}

// Output the CSS code
echo '<style>';
echo $css_code;
echo '</style>';
?>
```

