Here's a simple C function that converts an array of strings (argv) to a single null-terminated string:

```c
#include <stdio.h>
#include <string.h>

char *convert_argv_to_string(int argc, char **argv) {
    int i;
    size_t len = 0;
    char *result = malloc(sizeof(char) * (argc + 1)); // allocate memory for the result string

    if (!result) {
        return NULL;
    }

    for (i = 0; i < argc; i++) {
        len += strlen(argv[i]) + 1; // add the length of each argument plus the null terminator
    }

    result[len - 1] = '\0'; // set the last character to null

    for (i = 0; i < argc; i++) {
        strcat(result, argv[i]); // concatenate each argument to the result string
    }

    return result;
}

int main(int argc, char **argv) {
    char *result = convert_argv_to_string(argc, argv);

    if (result) {
        printf("Result: %s\n", result);
        free(result);
    } else {
        printf("Error: Could not allocate memory.\n");
    }

    return 0;
}
```

