To create a simple toast notification using React Context, follow these steps:

1. Create a `ToastContext` file:

```javascript
// ToastContext.js
import React from 'react';

const ToastContext = React.createContext();

function ToastProvider(props) {
  const [toasts, setToasts] = React.useState([]);

  function addToast(message, type) {
    setToasts((prevToasts) => [...prevToasts, { message, type }]);
  }

  return (
    <ToastContext.Provider value={{ addToast }}>
      {props.children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Create a `Toast` component:

```javascript
// Toast.js
import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

function Toast({ message, type }) {
  const { addToast } = useContext(ToastContext);

  React.useEffect(() => {
    addToast(message, type);
  }, [message, type, addToast]);

  return (
    <div className={`toast ${type}`}>
      {message}
    </div>
  );
}

export default Toast;
```

3. Use the `Toast` component in your app:

```javascript
// App.js
import React from 'react';
import ToastContext from './ToastContext';
import Toast from './Toast';

function App() {
  return (
    <ToastContext.Provider>
      <div className="App">
        <button onClick={() => Toast('Hello!', 'success')}>Success</button>
        <button onClick={() => Toast('Error!', 'error')}>Error</button>
        <Toast />
      </div>
    </ToastContext.Provider>
  );
}

export default App;
```

In this example, we have a `ToastContext` that provides an `addToast`

