2. Load your dataset of labeled sentences.
3. Preprocess the data by tokenizing and removing stop words.
4. Create a NaiveBayes classifier and fit it on the preprocessed data.
5. Use the trained model to predict the label for a new sentence.

Here's a concise and elegant C# code snippet that demonstrates these steps:
```csharp
using System;
using System.IO;
using System.Linq;
using Accord.MachineLearning;
using Accord.MachineLearning.Text;
using Accord.Math;

namespace TextClassification
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load dataset
            var dataset = new List<(string sentence, string category)>
            {
                ("Sports game was exciting", "Sports"),
                ("Politician made a controversial speech", "Politics"),
                ("Entertainer gave an amazing performance", "Entertainment"),
                // Add more labeled sentences here
            };

            // Preprocess data
            var tokenizer = new Tokenizer(new[] { "." });
            var stopWords = new[] { "the", "a", "an" };
            var preprocessor = new TextPreprocessing(tokenizer, stopWords);
            var preprocessedDataset = dataset.Select(x => (preprocessor.Transform(x.sentence), x.category));

            // Create NaiveBayes classifier
            var naiveBayes = new NaiveBayes();

            // Fit model on preprocessed data
            naiveBayes.Fit(preprocessedDataset);

            // Predict label for new sentence
            var newSentence = "The sports game was exciting";
            var prediction = naiveBayes.Predict(preprocessor.Transform(newSentence));

            Console.WriteLine($"Predicted label: {prediction}");
        }
    }
}
```
