Here's a PowerShell script that checks the ACLs of folders for SIDs found only in the SIDHistory of users or groups within your domain:

```powershell
# Define the domain name and the folder path to search
$domain = "your_domain_name"
$folderPath = "C:\path\to\your\folder"

# Function to check if a SID exists only in the SIDHistory of a user or group
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain -Filter {Name -eq $domain} -Properties DomainMode).DomainMode
    $searchBase = "DC=$domain,DC=com"
    $filter = "(objectClass=user)(memberOf:*-$(($sid.Value)-eq ''))"

    $results = Get-ADUser -Filter $filter -SearchBase $searchBase
    return ($results.Count -eq 0)
}

# Recursively check the folders and subfolders
function CheckFolderACLs($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        $uniqueSids = @()

        foreach ($access in $acl.Access) {
            if ($access.IdentityReference -match '^S-1-5-21-') {
                $sid = New-Object System.Security.Principal.SecurityIdentifier($access.IdentityReference)
                if (CheckSIDInSIDHistory($sid)) {
                    $uniqueSids += $sid
                }
            }
        }

        if ($uniqueSids.Count -gt 0) {
            Write-Host "Folder: $($_.FullName)"
            Write-Host "Unique SIDs found in ACLs:"
            $uniqueSids | ForEach-Object { Write-Host "- $_" }
            Write-Host "----------------------------------"
        }

        CheckFolderACLs($_.FullName)
    }
}

# Start the search
CheckFolderACLs($folderPath)
```

Replace `"your_domain_name"` with the name of your domain
